def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    my = [h[0] for h in history]
    op = [h[1] for h in history]
    lm = my[-1]
    lo = op[-1]

    opp_D = 0
    for x in op:
        if x == 'D':
            opp_D += 1
    opp_C = n - opp_D

    # If the opponent has never defected, start a short probe and keep
    # defecting while they remain cooperative. This strongly exploits
    # unconditional and very forgiving opponents.
    if opp_D == 0:
        if n >= 5:
            return 'D'
        return 'C'

    # Count defections that look unprovoked: opponent D after our C.
    unprov = 0
    recent_unprov = 0
    start_recent = n - 10
    if start_recent < 0:
        start_recent = 0
    for i in range(n):
        if op[i] == 'D':
            if i == 0 or my[i - 1] == 'C':
                unprov += 1
                if i >= start_recent:
                    recent_unprov += 1

    # Learn how opponent responds to our previous action.
    c_tot = 0
    d_tot = 0
    c_to_c = 0
    d_to_c = 0
    for i in range(n - 1):
        if my[i] == 'C':
            c_tot += 1
            if op[i + 1] == 'C':
                c_to_c += 1
        else:
            d_tot += 1
            if op[i + 1] == 'C':
                d_to_c += 1

    pC = c_to_c / c_tot if c_tot else 1.0
    pD = d_to_c / d_tot if d_tot else 0.0

